--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `sku` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `unit_id` bigint(20) unsigned DEFAULT NULL,
  `weight` decimal(10,3) DEFAULT NULL,
  `base_price` decimal(10,2) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  KEY `products_category_id_index` (`category_id`),
  KEY `products_is_active_index` (`is_active`),
  KEY `products_unit_id_foreign` (`unit_id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=138 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (86,'Game Garcia y Vega Natural Silver Cigarillos (2 for $1.29 Box)','CIG-GAM-NSILV','Game Garcia y Vega Natural Silver Cigarillos crafted with all-natural Connecticut shade leaf wrappers. Pre-priced at 2 Cigars for $1.29 in foil fresh resealable pouches. Display box contains 30 pouches (60 cigars total). High margin counter display essential for C-stores and smoke shops.',54,14,1.250,34.50,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(87,'Swisher Sweets Classic Cigarillos (2-Pack Foil Pouch Display Box)','CIG-SWI-CLAS','Swisher Sweets Classic Cigarillos feature a signature sweet blend with a smooth, slow burning tobacco wrapper. Packaged in stay-fresh resealable 2-cigar foil pouches. Display box contains 30 pouches (60 cigars total). #1 best-selling wholesale cigarillo line across convenience stores nationwide.',54,14,1.200,33.99,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(88,'Dutch Masters Palma Natural Leaf Cigars (Display Box of 40)','CIG-DUT-PLM40','Dutch Masters Palma Natural Connecticut Shade Leaf cigars crafted since 1912. Renowned for their slow, even burn and rich, mellow aroma with natural tobacco leaf wrapping. Upright display box contains 40 individually cellophane-wrapped premium Palma cigars. Retailer counter staple.',55,14,1.800,42.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(89,'Dutch Masters Palma Hand Selected Natural Leaf (55-Count Open Tray Display)','CIG-DUT-TRY55','Dutch Masters Palma hand-selected natural Connecticut shade leaf cigars in an attractive retail counter open-tray display. Sealed fresh for maximum moisture and aroma retention. Tray holds 55 single cigars ready for quick point-of-sale impulse purchases.',55,14,2.400,54.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(90,'Middleton\'s Black & Mild Pipe Tobacco Cigars (10 Packs of 5 Cigars Display)','CIG-MID-BKM50','Middleton\'s Black & Mild original pipe-tobacco cigars with ivory plastic tips. Packed with premium aromatic Cavendish and Virginia pipe tobaccos delivering an unmistakable aroma and smooth draw. Display carton contains 10 packs of 5 cigars each (50 plastic-tipped cigars total).',57,14,1.650,46.50,1,'2026-09-04 00:00:28','2026-09-04 00:08:09'),(91,'White Owl Mango Slow Burn Cigarillos (Save on 2 Cigars Display Box)','CIG-OWL-MNG60','White Owl Mango slow-burn cigarillos infuse luscious ripe tropical mango essence with smooth sheet-wrapped tobacco filler. Foil fresh sealed 2-cigar pouches keep cigars fresh from factory to customer. Display box contains 30 pouches (60 cigars total). High customer demand item.',54,14,1.150,32.50,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(92,'Swisher Sweets BLK Smooth Pipe Tip Cigarillos (15 Foil Packs of 2)','CIG-SWI-BLK30','Swisher Sweets BLK Smooth Pipe Tip Cigarillos feature rich English pipe tobacco blends encased in dark wrapper leaf with premium reusable black tips. Display box contains 15 resealable foil pouches with 2 tip cigarillos per pouch (30 cigars total). Modern aesthetic with smooth aroma.',57,14,0.950,26.99,1,'2026-09-04 00:00:28','2026-09-04 00:08:09'),(93,'LooseLeaf Cookies Cinnamon Milk Natural Leaf Wraps (8 Packs of 2 Wraps)','CIG-LOO-CIN16','LooseLeaf Cookies Cinnamon Milk limited edition all-natural whole leaf wraps. Hand cut from 100% premium whole leaf tobacco with perfectly cut edges and no thick veins. Infused with warm cinnamon and sweet cream dessert notes. Display box contains 8 pouches of 2 natural leaf wraps.',56,14,0.600,28.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(94,'Swisher Sweets Leaf All Natural Tobacco Cigars (Honey, Original & Sweet Aromatic)','CIG-SWI-LEAF30','Swisher Sweets Leaf cigars crafted from rustic, 100% all-natural tobacco wrapper leaf for an authentic, bold, slow-burning smoke. Available in top consumer flavors including Honey, Original, and Sweet Aromatic. Packaged in 3-cigar stay-fresh foil pouches. Display box contains 10 pouches (30 cigars).',56,14,0.850,24.95,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(95,'Backwoods Russian Cream All Natural Leaf Cigars (8 Packs of 5 Cigars Box)','CIG-BAK-RUS40','Backwoods Russian Cream cigars are wrapped in aged 100% natural broadleaf tobacco with an unfinished frayed head and tapered body. Infused with smooth vodka, rich dark coffee, and sweet fresh cream notes. Upright display box contains 8 foil pouches of 5 cigars (40 cigars total). High velocity seller.',56,14,1.400,48.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(96,'Cheyenne Filtered Little Cigars 100\'s (Carton of 10 Hard Packs)','CIG-CHY-LTL100','Cheyenne 100\'s Filtered Little Cigars made in the USA with premium American-grown tobaccos. Features a smooth firm filter delivering rich taste at an economical price point. Available in Full Flavor, Light, Menthol, and Vanilla. Carton contains 10 hard packs of 20 cigars (200 filtered cigars total).',58,15,0.750,22.50,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(97,'Dutch by Dutch Masters Berry Fusion Burst Cigarillos (Save More on 2 Box)','CIG-DUT-BRY60','Dutch by Dutch Masters Berry Fusion Burst slow burn cigarillos. Rolled with all natural leaf wrappers and filled with sweet berry fusion aroma for a smooth and fragrant smoke. Display box contains 30 stay-fresh resealable 2-cigar foil pouches (60 cigars total). Eye-catching pink & black packaging.',54,14,1.200,34.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(99,'Premium Heavyweight 100% Cotton Crew Neck T-Shirts (Dozen Bundle 12-Pack)','APP-TSH-DZ12','Classic heavyweight 6.0 oz 100% preshrunk cotton plain crew neck t-shirts. Features double-needle stitching, taped neck and shoulders, and tear-away tags. Wholesale dozen bundle includes pre-sorted size breakdown (3 Medium, 4 Large, 3 XL, 2 2XL) in classic solid White or Black.',62,10,4.800,48.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(100,'Global Classic Red 100\'s Filtered Cigarettes (Master Carton of 10 Packs)','CIG-GLO-RED100','Global Classic Red 100\'s premium American blend filtered cigarettes made in the U.S.A. Crafted with fine Virginia and toasted Burley tobacco for a full-flavor rich smoking profile. Master retail carton contains 10 hard flip-top packs with 20 cigarettes per pack (200 cigarettes total).',58,15,0.700,38.50,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(101,'American Club Expanded Pipe Tobacco 16oz Resealable Bag (+33% Volume)','TOB-AMC-16OZ','American Club expanded pipe tobacco made in the USA by Lake Erie Tobacco Company. Specially processed to offer 33% more volume per ounce for maximum pipe and RYO rolling yields. Available in Red (Regular Full Flavor), Green (Cool Menthol), and Blue (Smooth Mellow). Fresh-zip 16oz (1 lb) stand-up pouch.',57,16,1.050,14.50,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(102,'Cheyenne Pipe Tobacco 16oz Resealable Fresh Bag (Red, Gold & Menthol)','TOB-CHY-16OZ','Cheyenne 16oz Pipe Tobacco blended with high-grade American leaf carefully aged and ribbon cut for a smooth, consistent smoking experience. Packaged in moisture-barrier resealable bags. Available in Red (Full Bold Taste), Gold (Mellow Smooth), and Menthol (Crisp Refreshing). 16oz (1 lb) Net Weight.',57,16,1.050,13.99,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(103,'Automotive Fluids & Car Care Retail Display Combo (Pennzoil, DEF, Mag1 & Little Trees)','AUT-CMB-KIT','Complete high-margin C-Store automotive counter starter kit. Includes: Pennzoil 5W-30 Motor Oil (1 Qt), Mag1 SAE 5W-30 (1 Qt), Prime Guard UltraPure DEF Fluid (2.5 Gal box), Power Blast -20°F Windshield Washer (1 Gal), SeaFoam Motor Treatment (16 oz), and Little Trees Black Ice Air Fresheners (Card of 24).',64,11,18.500,89.00,1,'2026-09-04 00:00:28','2026-09-04 00:00:28'),(106,'Good Times HD High Definition Palma Pure Silver Cigars (Display Box of 40)','CIG-GDT-HD40','Good Times HD (High Definition) Palma Pure Silver cigars with 100% natural leaf wrapper. Engineered for an effortless draw, consistent slow burn, and mild, clean finish. Display carton holds 40 individually wrapped natural leaf cigars. Outstanding value point-of-sale cigar product for retail stores.',55,14,1.700,31.90,1,'2026-09-04 00:00:29','2026-09-04 00:00:29'),(107,'C-Store OTC Emergency Medicine & Health Care Display Assortment (6 Boxes / 200+ Packets)','OTC-MED-ASST','Complete convenience store over-the-counter travel and emergency medicine assortment. Features 6 pre-packed hanging/shelf dispenser display boxes: Pepto Bismol Chewables (32 packets), BC Fast Pain Relief (36 packets), BC Arthritis (12 packets), Benadryl Allergy (60 packets), Goody\'s Extra Strength (24 packets), Vicks DayQuil Severe (32 packets), and Motrin IB (50 packets). Essential 100% markup C-store category.',63,11,3.200,94.00,1,'2026-09-04 00:00:29','2026-09-04 00:00:29'),(108,'Assorted Summer Outdoor Sun Hats, Sombreros & Boonie Hats (12-Piece Assortment)','APP-HAT-ASST12','Wholesale dozen assortment of high-demand outdoor headwear for gas stations and convenience stores. Includes: Woven Straw Lifeguard Sombreros with Mexican Flag patch and chin cord, Digital Camouflage Wide-Brim Boonie Hats with breathable mesh vents, and Solid Black Tactical Bucket Hats. Pre-tagged with barcode.',62,10,3.800,66.00,1,'2026-09-04 00:00:29','2026-09-04 00:00:29'),(109,'Rotating Countertop Sunglasses Spinner Tower Display (Pre-Loaded with 72 Pairs)','DIS-SGL-SPN72','Turnkey retail sunglasses display program. Heavy-duty 4-sided rotating acrylic spinner tower equipped with dual side mirrors, pre-loaded with 72 assorted top-selling UV400 polarized men\'s and women\'s sunglasses (sport wrap, aviator, driving, polarized). Retail ready pre-priced at $9.99–$14.99 each. Yields over $700 in retail sales.',61,11,14.200,185.00,1,'2026-09-04 00:00:29','2026-09-04 00:00:29'),(110,'Illuminated Lockable Glass Display Tower with 40 Spring-Assisted Tactical Knives','DIS-KNF-TWR40','High-security premium illuminated lockable retail display case. Features high-output internal LED edge lighting, tamper-resistant lock and dual keys, and 40 individual slots pre-loaded with 40 assorted spring-assisted stainless steel tactical folding knives (serrated, tanto, drop point, rainbow titanium, and camo handles). Massive impulse profit generator.',61,11,22.000,220.00,1,'2026-09-04 00:00:29','2026-09-04 00:00:29'),(112,'Tylenol Extra Strength 500mg Caplets (50 Pouches of 2 Display Box)','MED-TYL-500','Official C-store countertop dispenser box containing 50 individual tamper-evident packets of 2 Tylenol Extra Strength 500mg acetaminophen caplets. Fast relief for headaches, backaches, and fever.',69,14,0.450,34.50,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(113,'Advil Pain Reliever & Fever Reducer 200mg (50 Packets of 2 Display Box)','MED-ADV-200','Convenient counter dispenser box with 50 individual 2-tablet packets of Advil Ibuprofen 200mg. The #1 doctor-recommended pain reliever for joint pain, headache, and muscle aches.',69,14,0.400,33.75,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(114,'Vicks DayQuil & NyQuil Severe Cold & Flu LiquidCaps (24-Count Display)','MED-VIC-SEV','Wholesale combo counter pack featuring 12 DayQuil Severe and 12 NyQuil Severe co-pack units. Maximum strength relief for coughing, congestion, sore throat, and sinus pressure.',70,14,0.600,48.90,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(115,'Pepto Bismol Chewable Tablets 5-Symptom Relief (30 Packets Box)','MED-PEP-CHEW','30 pocket packets each with 2 chewable bismuth subsalicylate tablets. Fast soothing relief for nausea, heartburn, indigestion, upset stomach, and diarrhea.',71,14,0.350,26.80,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(116,'Bayer Genuine Aspirin 325mg Pain Reliever (50 Pouches of 2 Box)','MED-BAY-325','50 pouches of 2 genuine Bayer 325mg coated aspirin tablets. Effective temporary pain relief and heart-health support for gas station and C-store customers.',69,14,0.380,24.50,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(117,'Alka-Seltzer Original Fast Relief Effervescent (36 Foil Packs of 2)','MED-ALK-ORIG','Original bubbly effervescent antacid and pain relief tablets in foil pouches. Speedy relief of acid indigestion, sour stomach, heartburn, and headache.',71,14,0.420,22.95,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(118,'Benadryl Allergy Ultratabs Antihistamine 25mg (24 Pouches of 2 Display)','MED-BEN-25','24 two-tablet pouches of Benadryl 25mg diphenhydramine HCl allergy tablets. Effective relief from hay fever, allergy symptoms, itchy watery eyes, and runny nose.',72,14,0.300,28.50,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(119,'Visine Red Eye Comfort Lubricant Eye Drops 0.5oz (12 Bottles Display)','MED-VIS-RED','12 individual 0.5 fl oz sterile squeeze bottles with red eye comfort formula. Gets the red out fast and relieves dryness from smoke and lack of sleep.',73,14,0.550,39.99,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(120,'Excedrin Extra Strength Caplets (50 Packets of 2 Display Box)','MED-EXC-STR','Fast acting headache and migraine formula with acetaminophen, aspirin, and caffeine. Countertop gravity feed dispenser box of 50 packets.',69,14,0.400,32.90,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(121,'Dramamine Original Motion Sickness Relief (24 Travel Packs Box)','MED-DRA-MOT','24 travel pouches containing 2 dimenhydrinate 50mg tablets each. Prevents and relieves motion sickness, nausea, and dizziness for road trips and commuting.',71,14,0.320,29.50,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(122,'ChapStick Classic Original Lip Balm (Countertop Gravity Display 48 Tubes)','HEA-CHA-LIP','Display cylinder with 48 tubes of ChapStick Classic Original 0.15oz lip balm. High rotation impulse item for checkout counters and register lanes.',80,14,0.650,44.90,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(123,'Colgate Total Whitening Toothpaste Travel Size 0.85oz (24 Pack Display)','HEA-COL-TP','24 pack travel size 0.85oz tubes of Colgate Total Whitening fluoride toothpaste. Perfect for convenience stores, hotels, and travel centers.',81,14,0.700,21.50,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(124,'Old Spice High Endurance Pure Sport Deodorant 2.25oz (12 Sticks Pack)','HEA-OLD-DEO','Wholesale shrink-wrapped 12-pack of Old Spice Pure Sport High Endurance aluminum-free deodorant sticks. Long lasting 48-hour odor protection.',82,13,0.950,34.80,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(125,'Gillette Foamy Regular Shaving Cream 11oz Can (Case of 12 Cans)','HEA-GIL-SHV','Full master case of 12 cans of Gillette Foamy Regular shaving cream with Comfort Glide formula. Rich, thick lather for an effortless close shave.',78,15,4.200,28.50,1,'2026-09-14 00:01:16','2026-09-14 00:01:16'),(126,'Trojan Magnum Lubricated Large Condoms (24 Packs of 3 Display Box)','SEX-TRO-MAG','24 retail boxes with 3 premium Trojan Magnum lubricated latex condoms each. Larger than standard condoms for extra comfort with silky smooth lubricant.',86,14,0.500,54.00,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(127,'Durex Extra Sensitive Ultra Thin Lubricated Condoms (18 Packs of 3 Box)','SEX-DUR-EXT','18 retail 3-packs of Durex Extra Sensitive ultra thin lubricated condoms. Designed to enhance sensitivity and connection with trusted strength.',86,14,0.450,42.50,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(128,'K-Y Jelly Water Based Personal Lubricant 4oz Tube (Pack of 12)','SEX-KY-LUBE','Wholesale box of 12 tubes of genuine K-Y Jelly 4oz water-based lubricant. Safe, natural feeling formula compatible with latex condoms.',87,13,1.600,46.80,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(129,'Duracell Coppertop AA Alkaline Batteries (Contractor 24-Pack Box)','GEN-DUR-AA','24 AA long-life alkaline batteries in bulk contractor box packaging. Engineered for everyday household electronics and emergency equipment.',98,14,0.600,22.50,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(130,'Energizer Max AAA Alkaline Long-Lasting Batteries (24-Pack Box)','GEN-ENR-AAA','Pack of 24 AAA Energizer Max high performance alkaline batteries. PowerSeal Technology holds power up to 10 years in storage.',98,14,0.350,21.90,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(131,'Pennzoil Platinum Full Synthetic Motor Oil 5W-30 (Case of 6 x 1-Quart)','AUT-PEN-5W30','Case of 6 individual 1-quart bottles of Pennzoil Platinum Full Synthetic 5W-30 made from natural gas. Superior wear protection and fuel economy.',95,15,5.800,42.00,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(132,'Peak Original Antifreeze & Coolant 50/50 Prediluted (Case of 6 x 1-Gallon)','AUT-PEA-AF','Case of six 1-gallon jugs of Peak 50/50 prediluted all-makes all-models antifreeze coolant. Guaranteed protection for up to 5 years or 150,000 miles.',94,15,24.000,49.50,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(133,'Little Trees Air Fresheners Assorted Top Scents (72-Piece Counter Display)','AIR-LIT-TRE','72-piece assorted display featuring Black Ice, Vanillaroma, Strawberry, Caribbean Colada, and New Car Scent. America’s favorite car freshener.',115,14,0.850,39.50,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(134,'BIC Classic Maxi Full-Size Pocket Lighters (50-Count Counter Display Tray)','LGT-BIC-MAX','Authentic BIC Classic Maxi disposable lighter 50-count retail counter display tray. Assorted vibrant colors with child-resistant safety guard.',111,14,1.100,47.50,1,'2026-09-14 00:01:17','2026-09-14 00:01:17'),(135,'Newport Zero Ultra-Refined Butane Gas 300ml Can (Master Pack of 12 Cans)','LGT-NEW-BUT','Master carton of 12 cans of Newport Zero 300ml refined lighter fuel with near zero impurities. Universal nozzle adapters included in every cap.',112,13,3.200,36.00,1,'2026-09-14 00:01:18','2026-09-14 00:01:18'),(136,'Midol Complete Multi-Symptom Relief Caplets (24 Travel Pouches Display)','MED-MID-COM','Fast multi-symptom relief for cramps, bloating, water-weight gain, fatigue, backache and headache. Countertop box with 24 individual 2-caplet packets.',69,14,0.350,29.90,1,'2026-09-14 00:17:10','2026-09-14 00:17:10'),(137,'Johnson & Johnson BAND-AID Flexible Fabric Adhesive Bandages (Box of 30)','MED-BAN-FAB','Genuine BAND-AID brand flexible fabric adhesive bandages with Memory-Weave fabric that moves with you. Quilt-Aid comfort pad cushions wounds.',74,14,0.250,18.50,1,'2026-09-14 00:17:11','2026-09-14 00:17:11');
